sys_variable_value.value:
(function execute(inputs, outputs) {

    var claim = new GlideRecord('x_snc_insurance_0_claim');

    // Find claim using Claim Number
    claim.addQuery('claim_number', inputs.claim_number);
    claim.query();

    if (!claim.next()) {
        throw new Error('Claim ' + inputs.claim_number + ' not found.');
    }

    // Generate 6-digit OTP
    var otp = Math.floor(100000 + Math.random() * 900000).toString();

    // Store OTP
    claim.setValue('otp_code', otp);
    claim.setValue('otp_verified', false);
    claim.update();

    // Return success message
    outputs.success_message =
        'OTP generated successfully for claim ' +
        claim.getValue('claim_number');

})(inputs, outputs);

